import React from 'react';
import SectionHeading from './SectionHeading';
import Reveal from './Reveal';
import Icon from './icons';
import { skillGroups } from '../data/content';

export default function Skills() {
  return (
    <section id="skills" className="py-16 px-6 border-t border-zinc-200 dark:border-zinc-800">
      <div className="max-w-prose mx-auto">
        <Reveal>
          <SectionHeading eyebrow="Skills" heading="Toolbox" />
        </Reveal>

        <div className="mt-6 space-y-3">
          {skillGroups.map((group, idx) => (
            <Reveal key={group.title} delay={idx * 40}>
              <div className="flex flex-col sm:flex-row sm:items-baseline gap-x-3 gap-y-1 text-sm">
                <div className="flex items-center gap-1.5 shrink-0 sm:w-40 text-zinc-800 dark:text-zinc-200 font-medium">
                  <Icon name={group.icon} size={14} className="text-zinc-400 dark:text-zinc-600" />
                  {group.title}
                </div>
                <p className="text-zinc-600 dark:text-zinc-400">{group.items.join(', ')}</p>
              </div>
            </Reveal>
          ))}
        </div>
      </div>
    </section>
  );
}
